/* Original per-session hardlink scopes, derived from all fixed Session roots.
 * Same ordinary UID and marker bytes as the parent root holder. Never unlink. */
#include <dirent.h>
#define SL_LIMIT (128u*1024u*1024u)
struct sl_entry {int root_index,acquired;char *name;struct stat marker;};
static struct sl_entry *sl_entries;static size_t sl_count,sl_bytes;static struct held *sl_roots;
static int sl_add(int root_index,const char *name){size_t n=strlen(name);if(n<=5||strcmp(name+n-5,".json"))return 1;n-=5;if(n>160)return 0;for(size_t i=0;i<n;i++)if(!((name[i]>='a'&&name[i]<='z')||(name[i]>='A'&&name[i]<='Z')||(name[i]>='0'&&name[i]<='9')||name[i]=='_'||name[i]=='-'))return name[0]=='.';
 size_t need=sizeof(struct sl_entry)+n+sizeof(".json.save-lock");if(need>SL_LIMIT-sl_bytes)return 0;struct sl_entry *entries=realloc(sl_entries,(sl_count+1)*sizeof(*entries));if(!entries)return 0;sl_entries=entries;char *lock=malloc(n+sizeof(".json.save-lock"));if(!lock)return 0;memcpy(lock,name,n);memcpy(lock+n,".json.save-lock",sizeof(".json.save-lock"));memset(&sl_entries[sl_count],0,sizeof(*sl_entries));sl_entries[sl_count].root_index=root_index;sl_entries[sl_count++].name=lock;sl_bytes+=need;return 1;}
static int sl_scan(int root_index,int fd){int own=openat(fd,".",O_RDONLY|O_DIRECTORY|O_NOFOLLOW|O_CLOEXEC);if(own<0)return 0;DIR *dir=fdopendir(own);if(!dir){close(own);return 0;}int okay=1;struct dirent *entry;errno=0;while((entry=readdir(dir))){if(!strcmp(entry->d_name,".")||!strcmp(entry->d_name,".."))continue;if(!sl_add(root_index,entry->d_name)){okay=0;break;}errno=0;}if(errno)okay=0;closedir(dir);return okay;}
static int sl_compare(const void*a,const void*b){const struct sl_entry*x=a,*y=b;if(x->root_index!=y->root_index)return x->root_index<y->root_index?-1:1;return strcmp(x->name,y->name);}
static int sl_fixed(int root_index,const char*name){size_t need=sizeof(struct sl_entry)+strlen(name)+1;if(need>SL_LIMIT-sl_bytes)return 0;struct sl_entry *entries=realloc(sl_entries,(sl_count+1)*sizeof(*entries));if(!entries)return 0;sl_entries=entries;char *copy=strdup(name);if(!copy)return 0;memset(&sl_entries[sl_count],0,sizeof(*sl_entries));sl_entries[sl_count].root_index=root_index;sl_entries[sl_count++].name=copy;sl_bytes+=need;return 1;}
static int sl_begin(struct held *sources,int count,const char *host,const char *nonce){sl_roots=sources;for(int i=0;i<count;i++)if(!strcmp(sources[i].name,".session-store-lock")){if(!sl_scan(i,sources[i].directory))return 0;const char *subdirs[]={".migrations",".deletions"};for(unsigned j=0;j<2;j++){int fd=openat(sources[i].directory,subdirs[j],O_RDONLY|O_DIRECTORY|O_NOFOLLOW|O_CLOEXEC);if(fd<0){if(errno==ENOENT)continue;return 0;}struct stat st;int okay=!fstat(fd,&st)&&st.st_uid==getuid()&&sl_scan(i,fd);close(fd);if(!okay)return 0;}}
 for(int i=0;i<count;i++)if(!strcmp(sources[i].name,".goal-store.save.lock")&&!sl_fixed(i,".goal-native.save.lock"))return 0;
 if(sl_count)qsort(sl_entries,sl_count,sizeof(*sl_entries),sl_compare);size_t kept=0;for(size_t i=0;i<sl_count;i++){if(kept&&!sl_compare(&sl_entries[kept-1],&sl_entries[i])){free(sl_entries[i].name);continue;}sl_entries[kept++]=sl_entries[i];}sl_count=kept;
 for(size_t i=0;i<sl_count;i++){struct sl_entry *e=&sl_entries[i];struct held h=sources[e->root_index];h.name=e->name;if(!acquire(&h,host,nonce))return 0;e->marker=h.marker;e->acquired=1;}return 1;
}
static int sl_current(void){for(size_t i=0;i<sl_count;i++){struct sl_entry *e=&sl_entries[i];if(!e->acquired)return 0;struct held h=sl_roots[e->root_index];h.name=e->name;h.marker=e->marker;if(!current(&h))return 0;}return 1;}
static int sl_owned(struct held *h,const char *name){if(!sl_roots||!sl_count)return 0;struct sl_entry key;memset(&key,0,sizeof(key));key.root_index=(int)(h-sl_roots);key.name=(char*)name;struct sl_entry *e=bsearch(&key,sl_entries,sl_count,sizeof(*sl_entries),sl_compare);return e&&e->acquired;}
static void sl_close(void){for(size_t i=0;i<sl_count;i++)free(sl_entries[i].name);free(sl_entries);sl_entries=NULL;sl_count=sl_bytes=0;sl_roots=NULL;}
